// ---- Playground shim (do not edit) ----
// The playground's lib is ES2022. These lines add what lib.esnext.disposable
// would declare, and make sure Symbol.dispose exists at runtime.
interface SymbolConstructor { readonly dispose: unique symbol; }
interface Disposable { [Symbol.dispose](): void; }
(Symbol as { dispose?: symbol }).dispose ??= Symbol.for('Symbol.dispose');
// ----------------------------------------

const events: string[] = [];

function reserve(sku: string) {
  events.push(`reserve ${sku}`);
  return {
    sku,
    [Symbol.dispose]: () => {
      events.push(`release ${sku}`);
    },
  };
}

function retry(times: number) {
  return function <This, Args extends unknown[], Return>(
    method: (this: This, ...args: Args) => Return,
    _context: ClassMethodDecoratorContext<This, (this: This, ...args: Args) => Return>,
  ) {
    return function (this: This, ...args: Args): Return {
      for (let attempt = 1; ; attempt++) {
        try {
          return method.call(this, ...args);
        } catch (e) {
          if (attempt >= times) throw e;
        }
      }
    };
  };
}

class PaymentGateway {
  calls = 0;
  failuresLeft: number;

  constructor(failures: number) {
    this.failuresLeft = failures;
  }

  @retry(3)
  charge(amountCents: number): string {
    this.calls++;
    if (this.failuresLeft > 0) {
      this.failuresLeft--;
      throw new Error('Gateway timeout');
    }
    events.push(`charge ${amountCents}`);
    return `receipt-${amountCents}`;
  }
}

function placeOrder(skus: string[], gateway: PaymentGateway): string {
  // Each reservation is released when this function exits, in reverse order.
  using stack = new DisposableStackLite();
  for (const sku of skus) stack.use(reserve(sku));
  return gateway.charge(skus.length * 1000);
}

// A tiny stand-in for DisposableStack, which the ES2022 playground lib lacks.
class DisposableStackLite implements Disposable {
  #items: Disposable[] = [];
  use<T extends Disposable>(item: T): T {
    this.#items.push(item);
    return item;
  }
  [Symbol.dispose]() {
    for (const item of this.#items.reverse()) item[Symbol.dispose]();
  }
}

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<ReturnType<typeof reserve>[typeof Symbol.dispose], () => void>>;
type T2 = Expect<Equal<ReturnType<PaymentGateway['charge']>, string>>;

console.log(placeOrder(['TENT-2P', 'MUG-SET'], new PaymentGateway(0)), events);
